      SUBROUTINE RTORSCC     TRANSFERS MATRIX R TO RSCC ----------------------------------------------------------------------      INCLUDE 'ELM17A.CIN'      INCLUDE 'R.CIN'      INCLUDE 'RS.CIN'      INCLUDE 'T.CIN'      INCLUDE 'TS.CIN'      INCLUDE 'U.CIN'      INCLUDE 'US.CIN'C      DO 10 JK = 1, 36   10 RSL(JK) = RL(JK)      IF (NORD1 .GE. 2) THEN        DO 20 JKM = 1, 105   20   TSL(JKM) = TL(JKM)      ENDIF      IF (NORD1 .GE. 3) THEN        DO 30 JKLM = 1, 280   30   USL(JKLM) = UL(JKLM)      ENDIF      RETURN      END